// Define `int` as a concrete Rust integer type. Here we use `i64`
// to model unbounded mathematical integers for our purposes.
type int = i64;

fn cube_elements(a: Vec<int>) -> Vec<int> {
    // Map each element x to x * x * x and collect into a new Vec
    a.into_iter()
     .map(|x| x * x * x)
     .collect()
}

